// Generates src/lib/security/security-rules.generated.ts from
// src/lib/security/security-rules.json. The JSON is Zod-validated and every
// pattern passes the build-time safety check; the generated file is committed
// (mirrors the pricing/tool-registry manifest pattern) and the runtime scanner
// imports it, so the browser bundle never touches the raw JSON or regex
// compilation of unvalidated input.
//
// Run: npm run generate:security-rules
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";
import { tsImport } from "tsx/esm/api";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const jsonPath = join(root, "src/lib/security/security-rules.json");
const outPath = join(root, "src/lib/security/security-rules.generated.ts");

// Windows: tsImport/ESM loaders reject bare drive-letter paths ("d:...");
// import specifiers must be file:// URLs.
const schemaMod = await tsImport(
  pathToFileURL(join(root, "src/lib/security/security-rules.schema.ts")).href,
  import.meta.url,
);
const { SecurityRulesFileSchema, isSafeSecurityPattern, detectReDoS } =
  schemaMod;

function fail(msg) {
  console.error(`generate-security-rules: ${msg}`);
  process.exit(1);
}

const raw = JSON.parse(await readFile(jsonPath, "utf8"));
const parsed = SecurityRulesFileSchema.safeParse(raw);
if (!parsed.success) {
  fail(
    `security-rules.json failed schema validation:\n${JSON.stringify(parsed.error.format(), null, 2)}`,
  );
}

const ids = new Set();
for (const rule of parsed.data.rules) {
  if (ids.has(rule.id)) fail(`duplicate rule id "${rule.id}"`);
  ids.add(rule.id);
  if (!isSafeSecurityPattern(rule.pattern)) {
    const reason =
      detectReDoS(rule.pattern) ??
      "empty / over-long / non-compiling (new RegExp)";
    fail(`rule "${rule.id}" has an unsafe pattern: ${reason}`);
  }
}

// Content-derived version: any rule edit bumps the reported rulesVersion.
const version = createHash("sha256")
  .update(JSON.stringify(parsed.data, null, 0))
  .digest("hex")
  .slice(0, 16);

const banner =
  "// @generated by scripts/generate-security-rules.mjs - DO NOT EDIT.\n";
const body = `import type { SecurityRulesFile } from "./security-rules.schema.ts";

export const SECURITY_RULES_DATA: SecurityRulesFile = ${JSON.stringify(parsed.data, null, 2)};

export const SECURITY_RULES_VERSION: string = ${JSON.stringify(version)};
`;
await writeFile(outPath, banner + body, "utf8");

console.log("generate-security-rules");
console.log(
  "鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€",
);
console.log(`rules:   ${parsed.data.rules.length}`);
console.log(`version: ${version}`);
console.log(`wrote ${join("src/lib/security", "security-rules.generated.ts")}`);
